<template><div class="page"><header><div><h2>教学资源</h2><p>当前文件服务采用外部地址引用</p></div><button @click="open">新增资源</button></header><p v-if="message" class="error">{{ message }}</p><section class="grid"><article v-for="r in resources" :key="r.resourceId"><span>{{ resourceTypeLabel(r.resourceType) }}</span><h3>{{ r.resourceName }}</h3><p>{{ r.courseName }} · {{ r.uploadedByName }}</p><div><a :href="r.fileUrl||r.externalUrl||'#'" target="_blank">打开</a><button @click="remove(r)">删除</button></div></article><div v-if="resources.length===0" class="empty">暂无教学资源</div></section><teleport to="body"><div v-if="dialog" class="overlay" @click.self="dialog=false"><section class="modal"><h3>新增教学资源</h3><label>课程<select v-model="form.courseId"><option :value="0" disabled>请选择</option><option v-for="c in courses" :key="c.courseId" :value="c.courseId">{{ c.courseName }}</option></select></label><label>名称<input v-model.trim="form.resourceName"/></label><label>类型<select v-model="form.resourceType"><option v-for="t in types" :key="t.v" :value="t.v">{{ t.n }}</option></select></label><label>{{ fileBased?'文件地址':'外部链接' }}<input v-model.trim="form.url" placeholder="https://..."/></label><p v-if="formError" class="error">{{ formError }}</p><footer><button @click="dialog=false">取消</button><button class="primary" @click="save">保存</button></footer></section></div></teleport></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{createResource,deleteResource,getCoursePage,getResourcePage,resourceTypeLabel,type CourseListItem,type ResourceItem,type ResourceType}from'../../utils/teachingApi';const resources=ref<ResourceItem[]>([]),courses=ref<CourseListItem[]>([]),dialog=ref(false),message=ref(''),formError=ref('');const form=reactive({courseId:0,resourceName:'',resourceType:1 as ResourceType,url:''});const types=[{v:1 as ResourceType,n:'PPT'},{v:2 as ResourceType,n:'Word'},{v:3 as ResourceType,n:'PDF'},{v:4 as ResourceType,n:'视频链接'},{v:5 as ResourceType,n:'参考链接'},{v:6 as ResourceType,n:'其他'}];const fileBased=computed(()=>[1,2,3,6].includes(form.resourceType));const err=(e:unknown)=>e instanceof Error?e.message:'操作失败';async function load(){try{resources.value=(await getResourcePage({pageNum:1,pageSize:500})).records}catch(e){message.value=err(e)}}function open(){Object.assign(form,{courseId:0,resourceName:'',resourceType:1,url:''});dialog.value=true}async function save(){if(!form.courseId||!form.resourceName||!form.url){formError.value='请填写完整信息';return}try{await createResource({courseId:form.courseId,resourceName:form.resourceName,resourceType:form.resourceType,fileUrl:fileBased.value?form.url:undefined,externalUrl:fileBased.value?undefined:form.url});dialog.value=false;await load()}catch(e){formError.value=err(e)}}async function remove(r:ResourceItem){if(!confirm(`确认删除“${r.resourceName}”？`))return;try{await deleteResource(r.resourceId);await load()}catch(e){message.value=err(e)}}onMounted(async()=>{try{courses.value=(await getCoursePage({pageNum:1,pageSize:500})).records}catch(e){message.value=err(e)}await load()});
</script><style scoped>.page{height:100%;overflow:auto;padding:28px 36px;background:transparent;color:#172033}header{display:flex;justify-content:space-between;align-items:center}h2{margin:0}header p{color:#7b8495}header button,.primary{border:0;border-radius:8px;padding:9px 15px;background:#2563eb;color:#fff}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.grid article{padding:18px;background:#fff;border:1px solid #e7ebf1;border-radius:12px}.grid article>span{font-size:11px;color:#2563eb}.grid h3{margin:8px 0}.grid p{font-size:12px;color:#7b8495}.grid article div{display:flex;gap:8px}.grid a,.grid article button,.modal footer button{border:0;border-radius:7px;padding:7px 11px;background:#eef1f6;color:#4b5565;text-decoration:none;font-size:12px}.empty{padding:50px;text-align:center;color:#8992a2}.error{color:#b42336}.overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;background:#0f172a6b}.modal{width:min(500px,90%);padding:22px;background:#fff;border-radius:14px}.modal label{display:flex;flex-direction:column;gap:6px;margin:12px 0;color:#687386;font-size:12px}.modal input,.modal select{border:1px solid #dfe4ec;border-radius:8px;padding:9px;font:inherit}.modal footer{display:flex;justify-content:flex-end;gap:8px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style>
